    @Before public void ownRun(){assertEquals("local-v2-child-route-media-downloads",args.getString("literaryChildRouteMediaPhase"));assertTrue(args.getString("literaryRunId","").matches("[a-f0-9]{32}"));}
    private interface Work {void run()throws Exception;}
    private static void denied(Work work)throws Exception {boolean refused=false;try{work.run();}catch(Exception unavailable){refused=true;}assertTrue("Closed refusal required",refused);}
    private byte[] bytes(String locale,String scenario)throws Exception{return PlanetChildVault.fixturePassportMediaRouteBytes(context,"journey-one",locale,scenario);}
    private static PlanetChildPassport.Route route(String id,String locale,byte[] bytes)throws Exception {String hash="a".repeat(64);return new PlanetChildPassport.Route(id,2,2,"fixture-package",2,hash,hash,"fixture-policy",hash,locale,7,"android-google","RU",bytes);}
    private static Map<String,Object> row(Object... fields){Map<String,Object> value=new LinkedHashMap<>();for(int i=0;i<fields.length;i+=2)value.put((String)fields[i],fields[i+1]);return value;}
    @SuppressWarnings("unchecked") private static Map<String,Object> parse(byte[] bytes)throws Exception {java.lang.reflect.Method method=Class.forName("ru.probpera.literaryplanet.PlanetChildVault$LocalV2PackageJson").getDeclaredMethod("read",byte[].class,int.class);method.setAccessible(true);return(Map<String,Object>)method.invoke(null,bytes,PlanetChildPassport.MAX_ROUTE_BYTES);}
    private static byte[] canonical(Object value)throws Exception {java.lang.reflect.Method method=Class.forName("ru.probpera.literaryplanet.PlanetChildVault$LocalV2PackageJson").getDeclaredMethod("bytes",Object.class,boolean.class);method.setAccessible(true);return(byte[])method.invoke(null,value,true);}
    @SuppressWarnings("unchecked") private static Map<String,Object> media(Map<String,Object> snapshot){return(Map<String,Object>)((List<?>)snapshot.get("media")).get(0);}
    private static String sha(byte[] bytes)throws Exception {byte[] digest=java.security.MessageDigest.getInstance("SHA-256").digest(bytes);StringBuilder result=new StringBuilder();for(byte b:digest)result.append(String.format(Locale.ROOT,"%02x",b&255));return result.toString();}
    private static byte[] chunk(String name,byte[] bytes)throws Exception {java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] kind=name.getBytes(StandardCharsets.US_ASCII);out.write(java.nio.ByteBuffer.allocate(4).putInt(bytes.length).array());out.write(kind);out.write(bytes);java.util.zip.CRC32 crc=new java.util.zip.CRC32();crc.update(kind);crc.update(bytes);out.write(java.nio.ByteBuffer.allocate(4).putInt((int)crc.getValue()).array());return out.toByteArray();}
    private static byte[] staticPng()throws Exception {java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream(),compressed=new java.io.ByteArrayOutputStream();out.write(new byte[]{(byte)137,80,78,71,13,10,26,10});out.write(chunk("IHDR",java.nio.ByteBuffer.allocate(13).putInt(1).putInt(1).put(new byte[]{8,6,0,0,0}).array()));try(java.util.zip.DeflaterOutputStream zip=new java.util.zip.DeflaterOutputStream(compressed)){zip.write(new byte[]{0,0,0,0,0});}out.write(chunk("IDAT",compressed.toByteArray()));out.write(chunk("IEND",new byte[0]));return out.toByteArray();}
    @Test public void exactNarrationAndRawProvenanceRemainInsideCanonicalSavedBytes()throws Exception {byte[] raw=bytes("en","valid");try{assertEquals("journey-one",PlanetChildVault.validatePassportRouteSnapshot(raw));JSONObject snapshot=new JSONObject(new String(raw,StandardCharsets.UTF_8)),media=snapshot.getJSONArray("media").getJSONObject(0);assertEquals(2,snapshot.getInt("schemaVersion"));byte[] wav=android.util.Base64.decode(media.getString("encodedBase64"),android.util.Base64.NO_WRAP),quality=android.util.Base64.decode(media.getString("audioProvenanceBase64"),android.util.Base64.NO_WRAP);try{assertEquals(204,wav.length);assertEquals(160,PlanetChildMedia.preflight(wav,"audio/wav").length);JSONObject source=new JSONObject(new String(quality,StandardCharsets.UTF_8));assertEquals("en",source.getString("locale"));assertEquals("fixture-licensor",source.getString("licensorId"));assertEquals("same-locale-text",source.getString("reducedAudioFallback"));assertEquals(media.getJSONObject("payload").getString("scriptChecksum"),source.getString("scriptChecksum"));assertEquals("Synthetic English narration transcript.",media.getJSONObject("payload").getString("transcript"));}finally{Arrays.fill(wav,(byte)0);Arrays.fill(quality,(byte)0);}}finally{Arrays.fill(raw,(byte)0);}}
    @Test public void savedCodecDetachesExactBinaryTranscriptAndEvidenceBytes()throws Exception {byte[] raw=bytes("ru","valid");PlanetChildPassport.Route original=route("journey-one","ru",raw);PlanetChildPassport.Ledger saved=PlanetChildPassport.empty().saved(original),restored=null;byte[] encoded=saved.encode();try{restored=PlanetChildPassport.decode(encoded);assertEquals(saved,restored);saved.wipe();assertArrayEquals(raw,restored.routes.get(0).copy());}finally{if(restored!=null)restored.wipe();saved.wipe();Arrays.fill(raw,(byte)0);Arrays.fill(encoded,(byte)0);}}
    @Test public void localeSpecificDownloadsDoNotReplaceSiblingLocaleBytes()throws Exception {byte[] ru=bytes("ru","valid"),en=bytes("en","valid");PlanetChildPassport.Ledger saved=PlanetChildPassport.empty().saved(route("journey-one","ru",ru)).saved(route("journey-one","en",en));try{assertEquals(2,saved.routes.size());assertArrayEquals(ru,saved.routes.get(0).copy());assertArrayEquals(en,saved.routes.get(1).copy());PlanetChildPassport.Ledger renewed=saved.saved(route("journey-one","ru",ru));try{assertEquals(2,renewed.routes.size());assertSame(saved.routes.get(1),renewed.routes.get(1));assertArrayEquals(en,renewed.routes.get(1).copy());}finally{renewed.routes.get(0).wipe();}}finally{saved.wipe();Arrays.fill(ru,(byte)0);Arrays.fill(en,(byte)0);}}
