    @Test public void explicitMediaSummaryCountsRealBytesAndTranscriptUtf8()throws Exception {for(String locale:Arrays.asList("ru","en")){byte[] raw=bytes(locale,"valid");try{Map<String,Object> summary=PlanetChildVault.passportRouteMediaSummary(raw,locale);String transcript="ru".equals(locale)?"Синтетический текст озвучки.":"Synthetic English narration transcript.";assertEquals(locale,summary.get("locale"));assertEquals("downloaded",summary.get("audioStatus"));assertEquals(1L,summary.get("audioItemCount"));assertEquals(0L,summary.get("imageItemCount"));assertEquals(204L,summary.get("mediaByteLength"));assertEquals((long)transcript.getBytes(StandardCharsets.UTF_8).length,summary.get("transcriptByteLength"));assertTrue(raw.length>204);}finally{Arrays.fill(raw,(byte)0);}}}
    @Test public void retainedTextOnlySchemaNeverInfersEnglishOrRussianAudio()throws Exception {byte[] raw=PlanetChildVault.fixturePassportRouteBytes(context,"journey-one");try{for(String locale:Arrays.asList("ru","en")){Map<String,Object> summary=PlanetChildVault.passportRouteMediaSummary(raw,locale);assertEquals("text-only",summary.get("audioStatus"));assertEquals(0L,summary.get("audioItemCount"));assertEquals(0L,summary.get("mediaByteLength"));assertEquals(0L,summary.get("transcriptByteLength"));}}finally{Arrays.fill(raw,(byte)0);}}
