    @Test public void routeCapacityCountsAllLocalesWithoutEviction()throws Exception {PlanetChildPassport.Ledger saved=PlanetChildPassport.empty();try{for(int i=0;i<16;i++)for(String locale:Arrays.asList("ru","en")){String id="route-"+i;byte[] raw=PlanetChildVault.fixturePassportMediaRouteBytes(context,id,locale,"valid");try{saved=saved.saved(route(id,locale,raw));}finally{Arrays.fill(raw,(byte)0);}}assertEquals(32,saved.routes.size());byte[] raw=PlanetChildVault.fixturePassportMediaRouteBytes(context,"overflow","en","valid");PlanetChildPassport.Route extra=route("overflow","en",raw);try{PlanetChildPassport.Ledger full=saved;denied(()->full.saved(extra));assertEquals(32,full.routes.size());}finally{extra.wipe();Arrays.fill(raw,(byte)0);}}finally{saved.wipe();}}
