        byte[] raw=bytes("en","large");PlanetChildPassport.Ledger saved=null,restored=null;byte[] encoded=null;
        try{assertEquals("journey-one",PlanetChildVault.validatePassportRouteSnapshot(raw));assertEquals(360044L,PlanetChildVault.passportRouteMediaSummary(raw,"en").get("mediaByteLength"));saved=PlanetChildPassport.empty().saved(route("journey-one","en",raw));encoded=saved.encode();restored=PlanetChildPassport.decode(encoded);saved.wipe();assertArrayEquals(raw,restored.routes.get(0).copy());}
