    @SuppressWarnings("unchecked") @Test public void largeRawNarrationEvidencePreservesSourceWhitespaceAndExactChecksum()throws Exception {
        byte[] raw=bytes("en","valid"),quality=null,extended=null,payloadBytes=null,saved=null;
        try{Map<String,Object> snapshot=parse(raw),asset=media(snapshot),payload=(Map<String,Object>)asset.get("payload");quality=android.util.Base64.decode((String)asset.get("audioProvenanceBase64"),android.util.Base64.NO_WRAP);Map<String,Object> evidence=parse(quality);evidence.put("loudnessReport","x".repeat(8192));evidence.put("qualityReport","y".repeat(8192));byte[] canonicalEvidence=canonical(evidence);try{extended=new byte[canonicalEvidence.length+2];extended[0]=' ';System.arraycopy(canonicalEvidence,0,extended,1,canonicalEvidence.length);extended[extended.length-1]='\n';}finally{Arrays.fill(canonicalEvidence,(byte)0);}payload.put("qualityChecksum",sha(extended));payloadBytes=canonical(payload);((Map<String,Object>)asset.get("entity")).put("contentChecksum",sha(payloadBytes));asset.put("audioProvenanceBase64",android.util.Base64.encodeToString(extended,android.util.Base64.NO_WRAP));saved=canonical(snapshot);assertEquals("journey-one",PlanetChildVault.validatePassportRouteSnapshot(saved));assertArrayEquals(extended,android.util.Base64.decode((String)media(parse(saved)).get("audioProvenanceBase64"),android.util.Base64.NO_WRAP));}
        finally{for(byte[] b:new byte[][]{raw,quality,extended,payloadBytes,saved})if(b!=null)Arrays.fill(b,(byte)0);}
    }
    @Test public void savedBase64RejectsMisplacedPaddingWhitespaceAndNonzeroPadBits()throws Exception {
        byte[] raw=bytes("en","valid");try{Map<String,Object> snapshot=parse(raw),asset=media(snapshot);String valid=(String)asset.get("encodedBase64");for(String bad:Arrays.asList("A","AA=","AA===","A=AA","====","AA-A",valid+"\n",valid.substring(0,valid.length()-4)+"AAAB=")){asset.put("encodedBase64",bad);byte[] changed=canonical(snapshot);try{denied(()->PlanetChildVault.validatePassportRouteSnapshot(changed));}finally{Arrays.fill(changed,(byte)0);}}asset.put("encodedBase64",valid);java.lang.reflect.Method decode=Class.forName("ru.probpera.literaryplanet.PlanetChildVault$LocalV2NarrationProvenance").getDeclaredMethod("decodeCanonical",String.class,int.class);decode.setAccessible(true);for(String bad:Arrays.asList("AB==","AAB="))denied(()->decode.invoke(null,bad,4));byte[] one=(byte[])decode.invoke(null,"AA==",1),two=(byte[])decode.invoke(null,"AAA=",2);try{assertEquals(1,one.length);assertEquals(2,two.length);denied(()->decode.invoke(null,"AAA=",1));}finally{Arrays.fill(one,(byte)0);Arrays.fill(two,(byte)0);}}
        finally{Arrays.fill(raw,(byte)0);}
    }
