    @SuppressWarnings("unchecked") @Test public void staticImageDownloadStoresExactBytesWithoutInferringNarration()throws Exception {
        byte[] raw=bytes("en","valid"),png=staticPng(),payloadBytes=null,saved=null,copy=null;PlanetChildPassport.Route route=null;
        try{Map<String,Object> snapshot=parse(raw),asset=media(snapshot),payload=row("role","image","altText","Synthetic static illustration","transcript",null,"scriptId",null,"scriptChecksum",null,"performerId",null,"qualityChecksum",null);payloadBytes=canonical(payload);asset.put("assetId","fixture-image");asset.put("entity",row("kind","image","id","fixture-image","contentChecksum",sha(payloadBytes)));asset.put("payload",payload);asset.put("policy",row("kind","image","id","fixture-image"));asset.put("inventoryKey","fixture-image.png");asset.put("sha256",sha(png));asset.put("bytes",(long)png.length);asset.put("mime","image/png");asset.put("encodedBase64",android.util.Base64.encodeToString(png,android.util.Base64.NO_WRAP));asset.put("audioProvenanceBase64",null);saved=canonical(snapshot);route=route("journey-one","en",saved);copy=route.copy();assertArrayEquals(saved,copy);assertEquals(1,PlanetChildMedia.preflight(png,"image/png").width);Map<String,Object> summary=PlanetChildVault.passportRouteMediaSummary(saved,"en");assertEquals("text-only",summary.get("audioStatus"));assertEquals(0L,summary.get("audioItemCount"));assertEquals(1L,summary.get("imageItemCount"));assertEquals((long)png.length,summary.get("mediaByteLength"));asset.put("audioProvenanceBase64","AA==");byte[] wrong=canonical(snapshot);try{denied(()->PlanetChildVault.validatePassportRouteSnapshot(wrong));}finally{Arrays.fill(wrong,(byte)0);}}
        finally{if(route!=null)route.wipe();for(byte[] b:new byte[][]{raw,png,payloadBytes,saved,copy})if(b!=null)Arrays.fill(b,(byte)0);}
    }
